def calculate_fibonacci(n):
    """Calculates the nth Fibonacci number using an iterative approach."""
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def is_prime(num):
    """Checks if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def sum_first_n_primes(n):
    """Calculates the sum of the first n prime numbers."""
    primes = []
    current_num = 2
    while len(primes) < n:
        if is_prime(current_num):
            primes.append(current_num)
        current_num += 1
    return sum(primes)

if __name__ == "__main__":
    # Task 1: 25th Fibonacci number
    fib_25 = calculate_fibonacci(25)

    # Task 2: Sum of the first 100 prime numbers
    prime_sum_100 = sum_first_n_primes(100)

    # Output results
    print(f"Results:")
    print(f"-------------------------------------------")
    print(f"25th Fibonacci number (F25): {fib_25}")
    print(f"Sum of the first 100 prime numbers: {prime_sum_100}")
    print(f"-------------------------------------------")

